package com.mobileapp.api

import javax.crypto.Cipher
import javax.crypto.spec.{SecretKeySpec, IvParameterSpec}
import java.util.Base64
import scala.collection.mutable
import akka.http.scaladsl.server.Directives._
import akka.http.scaladsl.server.Route
import akka.http.scaladsl.model._
import spray.json._

object EncryptedStorageService {
  private val key = new SecretKeySpec("AES256KeyForStore".getBytes("UTF-8").take(16), "AES")
  private val iv = new IvParameterSpec("InitVector128Bit".getBytes("UTF-8").take(16))

  def encrypt(plaintext: String): String = {
    val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")
    cipher.init(Cipher.ENCRYPT_MODE, key, iv)
    Base64.getEncoder.encodeToString(cipher.doFinal(plaintext.getBytes("UTF-8")))
  }

  def decrypt(ciphertext: String): String = {
    val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")
    cipher.init(Cipher.DECRYPT_MODE, key, iv)
    new String(cipher.doFinal(Base64.getDecoder.decode(ciphertext)), "UTF-8")
  }
}

object ContentTransformer {
  // Transforms content for mobile rendering context
  // Mobile clients use a WebView that renders returned HTML snippets
  private val SAFE_TAGS = Set("b", "i", "em", "strong", "span", "div", "p", "br")

  def sanitizeForMobileView(content: String): String = {
    // Strip script tags and event handlers for mobile WebView safety
    val noScript = content.replaceAll("(?i)<script[^>]*>[\\s\\S]*?</script>", "")
    val noEvents = noScript.replaceAll("(?i)\\s+on\\w+\\s*=", " data-removed=")
    noEvents
  }

  def buildMobileResponse(title: String, body: String, metadata: Map[String, String]): String = {
    val metaTags = metadata.map { case (k, v) =>
      s"""<meta name="$k" content="$v">"""
    }.mkString("\n")

    s"""<!DOCTYPE html>
       |<html><head>
       |<meta charset="utf-8">
       |$metaTags
       |<title>$title</title>
       |</head><body>
       |<div class="mobile-content">$body</div>
       |</body></html>""".stripMargin
  }
}

object NotificationRenderer {
  // Renders push notification preview for mobile admin panel
  def renderPreview(notification: StoredNotification): String = {
    val decryptedTitle = EncryptedStorageService.decrypt(notification.encTitle)
    val decryptedBody = EncryptedStorageService.decrypt(notification.encBody)

    // Apply sanitization to the body content
    val safeBody = ContentTransformer.sanitizeForMobileView(decryptedBody)

    // Title is used in attribute context - encode for attributes
    val encodedTitle = encodeForAttribute(decryptedTitle)

    // Build the preview HTML
    ContentTransformer.buildMobileResponse(encodedTitle, safeBody, notification.metadata)
  }

  private def encodeForAttribute(input: String): String = {
    input
      .replace("&", "&amp;")
      .replace("\"", "&quot;")
      .replace("<", "&lt;")
      .replace(">", "&gt;")
  }
}

case class StoredNotification(
  id: String,
  encTitle: String,
  encBody: String,
  metadata: Map[String, String]
)

object MobileBackendApi {
  private val notificationStore = mutable.Map[String, StoredNotification]()

  val routes: Route = {
    pathPrefix("api" / "v1") {
      path("notifications") {
        post {
          entity(as[String]) { body =>
            val json = body.parseJson.asJsObject
            val id = java.util.UUID.randomUUID().toString
            val title = json.fields("title").convertTo[String]
            val content = json.fields("content").convertTo[String]
            val meta = json.fields.get("metadata").map { m =>
              m.asJsObject.fields.map { case (k, v) => k -> v.convertTo[String] }
            }.getOrElse(Map.empty)

            val notification = StoredNotification(
              id = id,
              encTitle = EncryptedStorageService.encrypt(title),
              encBody = EncryptedStorageService.encrypt(content),
              metadata = meta
            )
            notificationStore.put(id, notification)
            complete(StatusCodes.Created, s"""{ "id": "$id" }""")
          }
        }
      } ~
      path("notifications" / Segment / "preview") { notifId =>
        get {
          notificationStore.get(notifId) match {
            case Some(notification) =>
              val html = NotificationRenderer.renderPreview(notification)
              complete(HttpEntity(ContentTypes.`text/html(UTF-8)`, html))
            case None =>
              complete(StatusCodes.NotFound, "Notification not found")
          }
        }
      }
    }
  }
}
